package com.hmdp.ai.runtime.retrieval;
import com.fasterxml.jackson.databind.ObjectMapper;import com.hmdp.ai.domain.artifact.Citation;import com.hmdp.ai.domain.knowledge.KnowledgeChunk;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class CitationBuilderTest {@Test void preservesPdfAndSpreadsheetLocations(){KnowledgeChunk chunk=new KnowledgeChunk("c","t","w","kb",1,"d",2,"dv","idx",0,"evidence","evidence","h",3,new float[]{1,2,3},.8,"application/pdf",7,"Policy","Root / Policy","Sheet1",3,5,1,4,10,20,"{\"title\":\"Policy Handbook\"}");Citation citation=new CitationBuilder(new ObjectMapper()).build(chunk,.91);assertEquals(7,citation.getPage());assertEquals("Sheet1",citation.getSheet());assertEquals("3-5",citation.getRowRange());assertEquals("Policy Handbook",citation.getTitle());assertEquals("c",citation.getChunkId());}}
